    'in a task': ['en una tarea', 'em uma tarefa', 'dans une tâche', 'in einer Aufgabe', 'タスクで', '在任务中', '할 일에서'],
    'in a doc': ['en un documento', 'em um documento', 'dans un document', 'in einem Dokument', 'ドキュメントで', '在文档中', '문서에서'],
